// exact-dft — L0: exact cyclotomic ring K = Q[t]/(Phi_d(t)).
//
// Representation: elements are dense coefficient vectors of Rationals of
// length phi(d) (spec L0). Phi_d is computed on demand, per d, with the
// *recursive division* method: x^n - 1 = prod_{e | n} Phi_e(x); to obtain
// Phi_n, divide x^n - 1 by Phi_e for every proper divisor e of n (memoized,
// recursive). Dense monic integer polynomials.
//
// Note (differential-testing design): the test-suite ground truth table
// (tests/phi_table.hpp) is generated by a *different* algorithm (Mobius
// product formula), so implementation bugs cannot hide.
//
// Phi_d cap: dense storage costs O(d) int64 per cached polynomial and the
// recursive division costs O(n * #divisors * n) word ops for Phi_n; the
// practical cap is d ~ 1e5 as in the spec. Enforced by kMaxD.
#pragma once
#include "rational.hpp"

#include <algorithm>
#include <map>
#include <mutex>
#include <numeric>
#include <stdexcept>
#include <string>
#include <vector>

namespace ed {

using Zpoly = std::vector<int64_t>;  // dense, index = power, monic-compatible

namespace detail {

inline std::vector<int64_t> divisors_of(int64_t n) {
    std::vector<int64_t> ds;
    for (int64_t i = 1; i * i <= n; ++i)
        if (n % i == 0) {
            ds.push_back(i);
            if (i != n / i) ds.push_back(n / i);
        }
    std::sort(ds.begin(), ds.end());
    return ds;
}

// Dense polynomial division by a monic polynomial; remainder discarded
// (callers guarantee exact divisibility).
inline Zpoly divide_monic(const Zpoly& a, const Zpoly& b) {
    if (b.back() != 1) throw std::logic_error("divide_monic: divisor not monic");
    Zpoly r = a;
    r.resize(std::max(a.size(), b.size()), 0);
    Zpoly q(r.size() >= b.size() ? r.size() - b.size() + 1 : 1, 0);
    for (size_t i = r.size() - b.size() + 1; i-- > 0;) {
        int64_t c = r[i + b.size() - 1];
        q[i] = c;
        if (c != 0)
            for (size_t j = 0; j < b.size(); ++j)
                r[i + j] -= c * b[j];  // int64 safe: Phi coefficients are tiny
    }
    while (q.size() > 1 && q.back() == 0) q.pop_back();
    return q;
}

inline Zpoly zmul(const Zpoly& a, const Zpoly& b) {
    Zpoly r(a.size() + b.size() - 1, 0);
    for (size_t i = 0; i < a.size(); ++i)
        if (a[i] != 0)
            for (size_t j = 0; j < b.size(); ++j)
                r[i + j] += a[i] * b[j];
    return r;
}

// Memoized Phi_n via recursive divisor division.
class PhiCache {
  public:
    const Zpoly& get(int d) {
        std::lock_guard<std::recursive_mutex> lock(mu_);
        auto it = cache_.find(d);
        if (it != cache_.end()) return it->second;
        if (d < 1) throw std::invalid_argument("Phi_d: d must be >= 1");
        Zpoly xd1(d + 1, 0);
        xd1[0] = -1;
        xd1[d] = 1;  // x^d - 1
        Zpoly num = xd1;
        for (int e : divisors_of(d)) {
            if (e == d) continue;
            num = divide_monic(num, get(e));
        }
        return cache_.emplace(d, std::move(num)).first->second;
    }
  private:
    std::recursive_mutex mu_;
    std::map<int, Zpoly> cache_;
};

inline PhiCache& phi_cache() {
    static PhiCache cache;
    return cache;
}

inline int64_t euler_phi(int64_t d) {
    int64_t result = d;
    int64_t n = d;
    for (int64_t p = 2; p * p <= n; ++p)
        if (n % p == 0) {
            while (n % p == 0) n /= p;
            result -= result / p;
        }
    if (n > 1) result -= result / n;
    return result;
}

}  // namespace detail

// Cap from the spec (dense Phi storage, O(d) memory per cached entry).
inline constexpr int kMaxCyclotomicOrder = 100000;

class Cyclotomic {
  public:
    Cyclotomic() : d_(1), c_{Rational(0)} {}
    explicit Cyclotomic(int d) : d_(d) {
        check_d();
        c_.assign((size_t)detail::euler_phi(d), Rational(0));
    }
    Cyclotomic(int d, std::vector<Rational> c) : d_(d), c_(std::move(c)) {
        check_d();
        if ((int64_t)c_.size() != detail::euler_phi(d))
            throw std::invalid_argument("Cyclotomic: coefficient count != phi(d)");
    }

    int d() const { return d_; }
    int64_t degree() const { return (int64_t)c_.size(); }  // = phi(d)
    const std::vector<Rational>& coeffs() const { return c_; }
    Rational operator[](size_t i) const { return c_[i]; }

    // The class of t (a primitive d-th root of unity zeta_d).
    static Cyclotomic zeta(int d) {
        Cyclotomic z(d);
        z.c_[0] = Rational(0);
        if (z.c_.size() > 1) z.c_[1] = Rational(1);
        else z.c_[0] = Rational(d == 1 ? 1 : -1);  // Phi_1 = t - 1 => t = 1; Phi_2 = t + 1 => t = -1
        return z;
    }

    static Cyclotomic rational(int d, Rational q) {
        Cyclotomic r(d);
        r.c_[0] = q;
        return r;
    }
    static Cyclotomic integer(int d, int64_t v) { return rational(d, Rational(v)); }

    bool is_zero() const {
        return std::all_of(c_.begin(), c_.end(), [](const Rational& r) { return r.is_zero(); });
    }

    Cyclotomic operator-() const {
        Cyclotomic r(*this);
        for (auto& q : r.c_) q = -q;
        return r;
    }

    Cyclotomic operator+(const Cyclotomic& o) const {
        require_same_ring(o);
        Cyclotomic r(*this);
        for (size_t i = 0; i < c_.size(); ++i) r.c_[i] += o.c_[i];
        return r;
    }
    Cyclotomic operator-(const Cyclotomic& o) const { return *this + (-o); }
    Cyclotomic operator*(const Cyclotomic& o) const {
        require_same_ring(o);
        const size_t n = c_.size(), m = o.c_.size();
        std::vector<Rational> prod(n + m - 1, Rational(0));
        for (size_t i = 0; i < n; ++i) {
            if (c_[i].is_zero()) continue;
            for (size_t j = 0; j < m; ++j) prod[i + j] += c_[i] * o.c_[j];
        }
        return Cyclotomic(d_, reduce(std::move(prod)));
    }
    Cyclotomic& operator+=(const Cyclotomic& o) { return *this = *this + o; }
    Cyclotomic& operator-=(const Cyclotomic& o) { return *this = *this - o; }
    Cyclotomic& operator*=(const Cyclotomic& o) { return *this = *this * o; }

    bool operator==(const Cyclotomic& o) const { return d_ == o.d_ && c_ == o.c_; }
    bool operator!=(const Cyclotomic& o) const { return !(*this == o); }

    // Exact exponentiation (k >= 0). zeta(d)^k uses the reduced exponent trick.
    Cyclotomic pow(int64_t k) const {
        if (k < 0) throw std::invalid_argument("pow: negative exponent");
        Cyclotomic result = integer(d_, 1);
        Cyclotomic base = *this;
        while (k > 0) {
            if (k & 1) result = result * base;
            base = base * base;
            k >>= 1;
        }
        return result;
    }

    // Reduce a coefficient vector of arbitrary length mod Phi_d (monic).
    std::vector<Rational> reduce(std::vector<Rational> a) const {
        const Zpoly& phi_poly = phi();
        const size_t deg = phi_poly.size() - 1;
        if (a.size() < deg) return a;
        for (size_t i = a.size(); i-- > deg;) {
            Rational c = a[i];
            if (c.is_zero()) continue;
            a[i] = Rational(0);
            for (size_t j = 0; j < deg; ++j) a[i - deg + j] -= c * Rational(phi_poly[j]);
        }
        a.resize(deg);
        return a;
    }

    const Zpoly& phi() const { return detail::phi_cache().get(d_); }

    // Ground-truth access used by tests: Phi_d as rationals.
    std::vector<Rational> phi_rational() const {
        std::vector<Rational> r;
        for (int64_t v : phi()) r.emplace_back(v);
        return r;
    }

  private:
    void check_d() const {
        if (d_ < 1 || d_ > kMaxCyclotomicOrder)
            throw std::invalid_argument("Cyclotomic: order d out of range [1, " +
                                        std::to_string(kMaxCyclotomicOrder) + "]");
    }
    void require_same_ring(const Cyclotomic& o) const {
        if (d_ != o.d_) {
            throw std::invalid_argument("Cyclotomic: mixing elements of Q(zeta_" +
                                        std::to_string(d_) + ") and Q(zeta_" +
                                        std::to_string(o.d_) + ")");
        }
    }

    int d_;
    std::vector<Rational> c_;
};

// Embed a cyclotomic element of Q(zeta_d) into Q(zeta_D) (requires d | D)
// by the standard compatibility zeta_d = zeta_D^{D/d}. Spec L3/L5: per-axis
// scalars compiled in Q(zeta_r) must act on data living in the composite
// ring Q(zeta_lcm of the axes). Coefficient vectors change shape (phi(d) ->
// phi(D)); values are preserved under the embedding map.
inline Cyclotomic embed(const Cyclotomic& c, int D) {
    const int d = c.d();
    if (D == d) return c;
    if (D < 1 || D > kMaxCyclotomicOrder || D % d != 0)
        throw std::invalid_argument("embed: target order D must be a multiple of d");
    if (c.is_zero()) return Cyclotomic(D);
    const Cyclotomic w = Cyclotomic::zeta(D).pow(D / d);  // order exactly d
    Cyclotomic acc(D);
    Cyclotomic wp = Cyclotomic::integer(D, 1);
    const auto& co = c.coeffs();
    for (size_t i = 0; i < co.size(); ++i) {
        if (!co[i].is_zero()) acc += Cyclotomic::rational(D, co[i]) * wp;
        if (i + 1 < co.size()) wp = wp * w;
    }
    return acc;
}

}  // namespace ed
